CREATE TABLE IF NOT EXISTS app_user (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 username VARCHAR(50) NOT NULL UNIQUE,
 password_hash VARCHAR(100) NOT NULL,
 display_name VARCHAR(50) NOT NULL,
 role VARCHAR(20) NOT NULL,
 status VARCHAR(20) NOT NULL DEFAULT 'ENABLED',
 created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE IF NOT EXISTS service_catalog (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 service_name VARCHAR(100) NOT NULL UNIQUE,
 display_name VARCHAR(100) NOT NULL,
 owner_name VARCHAR(50),
 current_version VARCHAR(30),
 runtime_status VARCHAR(20)
);
CREATE TABLE IF NOT EXISTS knowledge_base (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 name VARCHAR(100) NOT NULL UNIQUE, description VARCHAR(500),
 status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE', created_by BIGINT NOT NULL,
 created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS knowledge_document (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 kb_id BIGINT NOT NULL REFERENCES knowledge_base(id), title VARCHAR(200) NOT NULL,
 current_version_id BIGINT, created_by BIGINT NOT NULL,
 created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS document_version (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 document_id BIGINT NOT NULL REFERENCES knowledge_document(id),
 version_no VARCHAR(30) NOT NULL, original_name VARCHAR(255) NOT NULL,
 file_type VARCHAR(20) NOT NULL, file_size BIGINT NOT NULL,
 checksum VARCHAR(64) NOT NULL, storage_path VARCHAR(500) NOT NULL,
 process_status VARCHAR(20) NOT NULL DEFAULT 'PENDING',
 publish_status VARCHAR(20) NOT NULL DEFAULT 'DRAFT',
 effective_at TIMESTAMP, chunk_count INT NOT NULL DEFAULT 0,
 failure_reason VARCHAR(1000), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
 published_at TIMESTAMP, UNIQUE(document_id,version_no)
);
CREATE TABLE IF NOT EXISTS document_chunk_ref (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 version_id BIGINT NOT NULL REFERENCES document_version(id),
 vector_id VARCHAR(100) NOT NULL UNIQUE, chunk_index INT NOT NULL,
 page_number INT, content CLOB NOT NULL, UNIQUE(version_id,chunk_index)
);
CREATE TABLE IF NOT EXISTS app_seed (
 seed_key VARCHAR(100) PRIMARY KEY
);
CREATE TABLE IF NOT EXISTS conversation (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 user_id BIGINT NOT NULL, title VARCHAR(120) NOT NULL,
 created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
 updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS chat_message (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 conversation_id BIGINT NOT NULL REFERENCES conversation(id),
 role VARCHAR(20) NOT NULL, content CLOB NOT NULL, kb_id BIGINT,
 confidence_level VARCHAR(20), evidence_sufficiency VARCHAR(30),
 created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS message_citation (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 message_id BIGINT NOT NULL REFERENCES chat_message(id), version_id BIGINT NOT NULL,
 vector_id VARCHAR(100) NOT NULL, quote_text CLOB NOT NULL,
 page_number INT, title VARCHAR(200), version_no VARCHAR(30)
);
CREATE TABLE IF NOT EXISTS release_record (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,service_name VARCHAR(100) NOT NULL,version_no VARCHAR(30) NOT NULL,environment VARCHAR(30) NOT NULL,status VARCHAR(20) NOT NULL,released_at TIMESTAMP NOT NULL,summary VARCHAR(500));
CREATE TABLE IF NOT EXISTS incident_record (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,service_name VARCHAR(100) NOT NULL,symptom VARCHAR(500) NOT NULL,root_cause VARCHAR(1000),resolution VARCHAR(1000),status VARCHAR(20) NOT NULL,occurred_at TIMESTAMP NOT NULL,resolved_at TIMESTAMP);
CREATE TABLE IF NOT EXISTS diagnosis_record (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL,kb_id BIGINT NOT NULL,service_name VARCHAR(100) NOT NULL,symptom VARCHAR(1000) NOT NULL,error_context CLOB,result_content CLOB NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'OPEN',evidence_snapshot CLOB,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS knowledge_gap (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,kb_id BIGINT NOT NULL,normalized_question VARCHAR(1000) NOT NULL,sample_question VARCHAR(1000) NOT NULL,source_type VARCHAR(30) NOT NULL DEFAULT 'NO_EVIDENCE',priority VARCHAR(10) NOT NULL DEFAULT 'MEDIUM',occurrence_count INT NOT NULL DEFAULT 1,status VARCHAR(20) NOT NULL DEFAULT 'OPEN',processing_note VARCHAR(500),processing_at TIMESTAMP,processing_by BIGINT,resolution_type VARCHAR(30),resolution_note VARCHAR(500),first_seen_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,last_seen_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,resolved_at TIMESTAMP,resolved_by BIGINT,last_verification_result VARCHAR(30),UNIQUE(kb_id,normalized_question));
CREATE TABLE IF NOT EXISTS gap_occurrence (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,gap_id BIGINT NOT NULL REFERENCES knowledge_gap(id),conversation_id BIGINT REFERENCES conversation(id),question_message_id BIGINT REFERENCES chat_message(id),assistant_message_id BIGINT REFERENCES chat_message(id),feedback_id BIGINT,question VARCHAR(1000) NOT NULL,source_type VARCHAR(30) NOT NULL,evidence_summary VARCHAR(500),created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(feedback_id));
CREATE TABLE IF NOT EXISTS gap_verification (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,gap_id BIGINT NOT NULL REFERENCES knowledge_gap(id),question VARCHAR(1000) NOT NULL,evidence_sufficient BOOLEAN NOT NULL,result VARCHAR(30) NOT NULL,retrieval_summary VARCHAR(1000),operator_id BIGINT NOT NULL,notes VARCHAR(500),created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS message_feedback (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,message_id BIGINT NOT NULL REFERENCES chat_message(id),user_id BIGINT NOT NULL,rating VARCHAR(10) NOT NULL,comment_text VARCHAR(500),created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(message_id,user_id));
CREATE TABLE IF NOT EXISTS tool_call_audit (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL,tool_name VARCHAR(80) NOT NULL,parameter_summary VARCHAR(500),result_count INT NOT NULL,success BOOLEAN NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS diagnosis_tool_call_audit (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL,diagnosis_request_id VARCHAR(50) NOT NULL,tool_name VARCHAR(80) NOT NULL,model_requested BOOLEAN NOT NULL,authorization_granted BOOLEAN NOT NULL,success BOOLEAN NOT NULL,failure_category VARCHAR(50),duration_ms BIGINT NOT NULL,result_size INT NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sql_query_audit (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,request_id VARCHAR(50) NOT NULL,user_id BIGINT NOT NULL,question VARCHAR(500) NOT NULL,generated_sql VARCHAR(4000),validation_status VARCHAR(20) NOT NULL,execution_status VARCHAR(20) NOT NULL,latency_ms BIGINT,row_count INT NOT NULL DEFAULT 0,failure_reason VARCHAR(1000),created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS ai_call_log (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,request_id VARCHAR(50) NOT NULL,user_id BIGINT NOT NULL,scene VARCHAR(40) NOT NULL,model_name VARCHAR(80),latency_ms BIGINT,input_tokens INT NOT NULL DEFAULT 0,output_tokens INT NOT NULL DEFAULT 0,token_estimated BOOLEAN NOT NULL DEFAULT TRUE,status VARCHAR(20) NOT NULL,error_code VARCHAR(50),created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS ai_provider_call_audit (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,provider VARCHAR(40) NOT NULL,operation VARCHAR(40) NOT NULL,success BOOLEAN NOT NULL,failure_category VARCHAR(40),retry_count INT NOT NULL DEFAULT 0,circuit_state VARCHAR(20),latency_ms BIGINT NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS version_semantic_compare_audit (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,old_version_id BIGINT NOT NULL REFERENCES document_version(id),new_version_id BIGINT NOT NULL REFERENCES document_version(id),provider VARCHAR(40) NOT NULL,operation VARCHAR(40) NOT NULL,status VARCHAR(30) NOT NULL,failure_category VARCHAR(60),latency_ms BIGINT NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE USER IF NOT EXISTS ops_analytics PASSWORD 'ops-analytics-readonly';
GRANT SELECT ON service_catalog TO ops_analytics;
GRANT SELECT ON release_record TO ops_analytics;
GRANT SELECT ON incident_record TO ops_analytics;
ALTER TABLE chat_message ADD COLUMN IF NOT EXISTS kb_id BIGINT;
ALTER TABLE knowledge_gap ADD COLUMN IF NOT EXISTS source_type VARCHAR(30) NOT NULL DEFAULT 'NO_EVIDENCE';
ALTER TABLE knowledge_gap ADD COLUMN IF NOT EXISTS priority VARCHAR(10) NOT NULL DEFAULT 'MEDIUM';
ALTER TABLE knowledge_gap ADD COLUMN IF NOT EXISTS processing_note VARCHAR(500);
ALTER TABLE knowledge_gap ADD COLUMN IF NOT EXISTS processing_at TIMESTAMP;
ALTER TABLE knowledge_gap ADD COLUMN IF NOT EXISTS processing_by BIGINT;
ALTER TABLE knowledge_gap ADD COLUMN IF NOT EXISTS resolution_type VARCHAR(30);
ALTER TABLE knowledge_gap ADD COLUMN IF NOT EXISTS resolution_note VARCHAR(500);
ALTER TABLE knowledge_gap ADD COLUMN IF NOT EXISTS resolved_by BIGINT;
ALTER TABLE knowledge_gap ADD COLUMN IF NOT EXISTS last_verification_result VARCHAR(30);
